#include <stddef.h>
#include <stdint.h>
static void put64(uint8_t*out,size_t i,int64_t x){uint64_t v=(uint64_t)x;for(int b=0;b<8;b++)out[i*8+b]=(uint8_t)(v>>(8*b));}
int64_t highest_response_ratio_next(const int64_t*v,size_t n,uint8_t*out,size_t cap){if(!v||n<3||n>129)return -1;int64_t count=v[0];if(count<1||count>64||n!=(size_t)(1+2*count))return -1;int64_t a[64],b[64],tat[64];int done[64]={0};for(int i=0;i<count;i++){a[i]=v[1+2*i];b[i]=v[2+2*i];if(a[i]<0||a[i]>100000||b[i]<1||b[i]>1000)return -1;for(int j=0;j<i;j++)if(a[j]==a[i])return -1;}for(int i=1;i<count;i++)for(int j=i;j>0&&a[j]<a[j-1];j--){int64_t t=a[j];a[j]=a[j-1];a[j-1]=t;t=b[j];b[j]=b[j-1];b[j-1]=t;}if((size_t)count*8>cap||!out)return -2;int64_t now=0;for(int step=0;step<count;step++){int best=-1;int64_t num=0;for(int i=0;i<count;i++)if(!done[i]&&a[i]<=now){int64_t cand=now-a[i]+b[i];if(best<0||cand*b[best]>num*b[i]){best=i;num=cand;}}if(best<0){for(int i=0;i<count;i++)if(!done[i]&&(best<0||a[i]<a[best]))best=i;now=a[best];step--;continue;}tat[best]=now+b[best]-a[best];now+=b[best];done[best]=1;}for(int i=0;i<count;i++)put64(out,i,tat[i]);return count*8;}
